 pub proof fn lemma_always_every_msg_from_vrs_controller_carries_vrs_key(
     spec: TempPred<ClusterState>, cluster: Cluster, controller_id: int,
 )
     requires
         spec.entails(lift_state(cluster.init())),
         spec.entails(always(lift_action(cluster.next()))),
         cluster.type_is_installed_in_cluster::<VReplicaSetView>(),
         cluster.controller_models.contains_pair(controller_id, vrs_controller_model()),
     ensures
         spec.entails(always(lift_state(every_msg_from_vrs_controller_carries_vrs_key(controller_id)))),
 {
         // This is a state-only invariant about messages already present
         // in the in-flight set.
         //
         // Prove `always` from the assumed base invariant and the fact that
         // the cluster transition preserves it.
         assert_by(
             spec.entails(lift_state(every_msg_from_vrs_controller_carries_vrs_key(controller_id))),
             {
                 entails_preserved_by_always(
                     lift_state(every_msg_from_vrs_controller_carries_vrs_key(controller_id)),
                     lift_state(every_msg_from_vrs_controller_carries_vrs_key(controller_id)),
                 );
             },
         );

         spec.entails(always(lift_state(every_msg_from_vrs_controller_carries_vrs_key(controller_id))));
 }




 }

